var o={task:"업무",meeting:"회의",utterance:"회의 내용",github:"GitHub"};function g(n){return o[n]??n}var a=["task","meeting","utterance","github"];function f(n,t,e=80){if(n.length<=e)return n;let r=t.trim(),u=r===""?-1:n.toLowerCase().indexOf(r.toLowerCase());if(u===-1)return`${n.slice(0,e)}…`;let i=Math.max(0,u-Math.floor((e-r.length)/2)),l=Math.min(n.length,i+e);return`${i>0?"…":""}${n.slice(i,l)}${l<n.length?"…":""}`}function h(n,t){return n.kind==="utterance"&&n.meeting_id!==null?`/review.html?meeting=${n.meeting_id}`:n.meeting_id!==null?`/lobby.html?meeting=${n.meeting_id}&project=${t}`:n.task_id!==null?`/kanban.html?project=${t}`:null}function c(n,t){return n.trim().length>=2?!0:t!==null&&(t.assignee!==""||t.status!=="")}function d(n,t){return c(n,t)?null:n.trim().length===1?t===null?"두 글자 이상 적어 주세요.":"두 글자 이상 적거나, 업무 담당자·상태를 고르세요.":null}function p(n,t){if(n===null||n.assignee===""&&n.status==="")return null;let e=t.map(r=>r.kind).filter(r=>r!=="task");return e.length===0?null:`담당자·상태는 업무에만 걸립니다 — ${e.map(g).join("·")}에는 안 걸렸습니다.`}var s=30;function m(n,t=s){return n>=t}function x(n,t=s){return m(n,t)?`한 종류에 ${t}개까지만 보여 줍니다 — 더 있을 수 있으니 검색어를 좁혀 보세요`:null}function k(n){return a.map(t=>({kind:t,hits:n.filter(e=>e.kind===t)})).filter(t=>t.hits.length>0)}export{g as a,f as b,h as c,c as d,d as e,p as f,x as g,k as h};
